using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class RepairTreeTopLanding{
 const string F="Assets/Track/BackyardShortcuts/";static Transform root;static Material wood,dark;static WoodlandRoute b;
 static float Ground(Vector3 p)=>Physics.RaycastAll(new Vector3(p.x,250,p.z),Vector3.down,500,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).OrderBy(h=>h.distance).First().point.y;
 static void Part(string n,Vector3 p,Vector3 scale,Quaternion q,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(root);g.transform.SetPositionAndRotation(p,q);g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=m;Object.DestroyImmediate(g.GetComponent<Collider>());}
 static void Beam(string n,Vector3 a,Vector3 c,float w){Part(n,(a+c)*.5f,new(w,w,Vector3.Distance(a,c)),Quaternion.LookRotation(c-a),dark);}
 static void Deck(string name,float begin,float end,float width){var pts=new List<Vector3>();for(float s=begin;s<end;s+=.6f)pts.Add(b.At(s,out _));pts.Add(b.At(end,out _));var v=new List<Vector3>();var tri=new List<int>();for(int i=0;i<pts.Count;i++){var f=pts[Math.Min(i+1,pts.Count-1)]-pts[Math.Max(0,i-1)];var side=Vector3.Cross(Vector3.up,f).normalized;v.Add(pts[i]-side*width*.5f);v.Add(pts[i]+side*width*.5f);if(i>0){int a=(i-1)*2;tri.AddRange(new[]{a,a+2,a+1,a+1,a+2,a+3});}}
 var mesh=new Mesh();mesh.SetVertices(v);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh.RecalculateBounds();string file=F+name+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(file);if(saved){EditorUtility.CopySerialized(mesh,saved);Object.DestroyImmediate(mesh);mesh=saved;}else AssetDatabase.CreateAsset(mesh,file);var deck=new GameObject((begin<20?"Takeoff - ":"Landing - ")+name);deck.transform.SetParent(root);deck.AddComponent<MeshFilter>().sharedMesh=mesh;deck.AddComponent<MeshRenderer>().sharedMaterial=wood;deck.AddComponent<MeshCollider>().sharedMesh=mesh;
 for(float s=begin+.35f;s<end;s+=.78f){var p=b.At(s,out var f);Part(name+" plank",p+Vector3.up*.025f,new(width+.12f,.1f,.70f),Quaternion.LookRotation(f),((int)(s*2)%4==0)?dark:wood);}
 for(float s=begin+3;s<end-2;s+=9){var p=b.At(s,out var f);var side=Vector3.Cross(Vector3.up,f).normalized;foreach(float sign in new[]{-1f,1f}){var top=p+side*(width*.5f-.3f)*sign-Vector3.up*.35f;var bottom=top;bottom.y=Ground(bottom)-.12f;if(top.y>bottom.y+.3f){Beam("Timber grounded support",bottom,top,.24f);Beam("Tree-platform diagonal brace",Vector3.Lerp(bottom,top,.65f),p-side*1.4f*sign-Vector3.up*.3f,.18f);}}Beam("Platform cross bearer",p-side*(width*.5f+.25f)-Vector3.up*.2f,p+side*(width*.5f+.25f)-Vector3.up*.2f,.26f);}}
 public static string Main(){if(Application.isPlaying)throw new Exception("Edit mode required");EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardForward.unity");root=GameObject.Find("Backyard optional forest shortcuts").transform;wood=AssetDatabase.LoadAssetAtPath<Material>(F+"Weathered cedar.mat");dark=AssetDatabase.LoadAssetAtPath<Material>(F+"Old dark timber.mat");b=Object.FindObjectsByType<WoodlandRoute>().First(r=>r.title=="Tree-Top Trail");var old=b.points.ToArray();float end=b.Length,yEnd=Ground(old[^1]),rampY=Ground(b.At(15,out _)),lipY=rampY+1.6f,landingY=lipY+2.15f,s=0;
 float Profile(float station){if(station<=60)return landingY;float q=station-60;float mid=(yEnd-landingY+.75f)/(end-75);if(q<=20)return landingY+mid*q*q/40;if(station<=end-10)return landingY+mid*10+mid*(q-20);float u=station-(end-10);return yEnd-5*(mid-.15f)+mid*u+(-.15f-mid)*u*u/20;}
 for(int i=0;i<b.points.Length;i++){if(i>0)s+=Vector2.Distance(new(old[i].x,old[i].z),new(old[i-1].x,old[i-1].z));b.points[i].y=s<15?Ground(old[i]):s<=35?rampY-.12f*(s-15)+4*Mathf.Pow((s-15)/20,2):s<47?Mathf.Lerp(lipY,landingY,(s-35)/12):Profile(s);}
 foreach(Transform t in root.Cast<Transform>().ToArray()){bool surface=t.name.Contains("Tree-top plank trail")||t.name.Contains("Canopy launch boards")||t.name.Contains("Canopy offroad launch")||t.name=="Treehouse resting platform";bool supports=(t.name=="Platform cross bearer"||t.name=="Timber grounded support"||t.name=="Tree-platform diagonal brace")&&t.position.z<0;bool arrows=t.name=="Gold optional route chevron"&&t.position.z<0;if(surface||supports||arrows)Object.DestroyImmediate(t.gameObject);}
 b.entrySpeed=26;b.entrySpeedDistance=40;b.recommendedSpeed=19;Deck("Canopy offroad launch",15,35,5.2f);Deck("Tree-top plank trail continuous timber collision",47,end,4.7f);
 foreach(float station in new[]{63f,83f}){var p=b.At(station,out var f);Part("Treehouse resting platform",p-Vector3.up*.2f,new(6,.22f,3.2f),Quaternion.LookRotation(f),wood);}
 var gold=AssetDatabase.LoadAssetAtPath<Material>(F+"Shortcut gold.mat");foreach(float station in new[]{8f,22f,34f,62f,80f,98f}){var p=b.At(station,out var f)+Vector3.up*.12f;var side=Vector3.Cross(Vector3.up,f).normalized;foreach(float sign in new[]{-1f,1f}){var a=p-f*1.2f+side*.9f*sign;var c=p+f*.6f;Part("Gold optional route chevron",(a+c)*.5f,new(.16f,.16f,Vector3.Distance(a,c)),Quaternion.LookRotation(c-a),gold);}}
 EditorUtility.SetDirty(b);EditorSceneManager.MarkSceneDirty(root.gameObject.scene);EditorSceneManager.SaveScene(root.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllText("Docs/BackyardShortcuts/tree-profile.txt",$"Ramp starts 15m into optional corridor; lip station35 Y={lipY}; receiving deck station47 Y={landingY}; unchanged rejoin {b.points[^1]}");return "Raised ramp begins offroad at station15; measured-trajectory receiving deck and grounded supports rebuilt";
 }
}


